==> platform/provider.ts <==
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

const providers = new Map<string, aws.Provider>();

/**
 * The AWS provider a team deploys with: the stack's region, and default tags (team, env) on every resource.
 * Pass it as `{ provider }` to every resource and component.
 */
export function provider(team: string): aws.Provider {
    let p = providers.get(team);
    if (!p) {
        p = new aws.Provider(`${team}-aws`, {
            region: new pulumi.Config("aws").require("region") as aws.Region,
            defaultTags: { tags: { team, env: pulumi.getStack(), "managed-by": "pulumi" } },
        });
        providers.set(team, p);
    }
    return p;
}

==> platform/storage.ts <==
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export type DataClass = "public" | "internal" | "confidential";

export interface BucketArgs {
    /** The owning team; it must match the `src/<team>/` directory the bucket is declared in. */
    team: string;
    /** What the bucket holds. Confidential buckets must be protected in prod. */
    dataClass: DataClass;
}

/**
 * An S3 bucket with Acme's defaults: public access blocked, versioning on, server-side encryption, tags.
 */
export class Bucket extends pulumi.ComponentResource {
    public readonly bucket: aws.s3.Bucket;
    public readonly arn: pulumi.Output<string>;
    public readonly bucketName: pulumi.Output<string>;

    constructor(name: string, args: BucketArgs, opts?: pulumi.ComponentResourceOptions) {
        super("acme:storage:Bucket", name, args, opts);
        const tags = { team: args.team, "data-class": args.dataClass };
        this.bucket = new aws.s3.Bucket(name, { tags }, { parent: this });
        new aws.s3.BucketPublicAccessBlock(
            `${name}-public-access`,
            {
                bucket: this.bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            { parent: this },
        );
        new aws.s3.BucketVersioning(
            `${name}-versioning`,
            { bucket: this.bucket.id, versioningConfiguration: { status: "Enabled" } },
            { parent: this },
        );
        // Bug, on purpose (the showcase's component-implementation finding): public buckets skip encryption.
        if (args.dataClass !== "public") {
            new aws.s3.BucketServerSideEncryptionConfiguration(
                `${name}-encryption`,
                {
                    bucket: this.bucket.id,
                    rules: [{ applyServerSideEncryptionByDefault: { sseAlgorithm: "aws:kms" }, bucketKeyEnabled: true }],
                },
                { parent: this },
            );
        }
        this.arn = this.bucket.arn;
        this.bucketName = this.bucket.bucket;
        this.registerOutputs({ arn: this.arn, bucketName: this.bucketName });
    }
}

==> platform/db.ts <==
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export type Size = "small" | "medium" | "large";

const instanceClasses: Record<Size, string> = {
    small: "db.t4g.small",
    medium: "db.r6g.large",
    large: "db.r6g.2xlarge",
};

export interface PostgresArgs {
    /** The owning team; it must match the `src/<team>/` directory the database is declared in. */
    team: string;
    /** small (dev), medium or large (prod). */
    size: Size;
    /** The master password. Pass a secret: `config.requireSecret(...)`. */
    password: pulumi.Input<string>;
}

/**
 * A private, encrypted Postgres 16 instance with backups. Protect it in prod with `{ protect: true }`.
 */
export class Postgres extends pulumi.ComponentResource {
    public readonly endpoint: pulumi.Output<string>;

    constructor(name: string, args: PostgresArgs, opts?: pulumi.ComponentResourceOptions) {
        super("acme:db:Postgres", name, args, opts);
        const instance = new aws.rds.Instance(
            name,
            {
                engine: "postgres",
                engineVersion: "16.4",
                instanceClass: instanceClasses[args.size],
                allocatedStorage: 50,
                storageEncrypted: true,
                publiclyAccessible: false,
                username: "app",
                password: args.password,
                backupRetentionPeriod: 7,
                deletionProtection: pulumi.getStack() === "prod",
                skipFinalSnapshot: false,
                finalSnapshotIdentifier: `${name}-final`,
                tags: { team: args.team },
            },
            { parent: this },
        );
        this.endpoint = instance.endpoint;
        this.registerOutputs({ endpoint: this.endpoint });
    }
}

==> platform/network.ts <==
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface ServiceArgs {
    team: string;
    vpcId: pulumi.Input<string>;
    port: number;
    /** Put the service behind an internet-facing load balancer in these public subnets. */
    publicSubnetIds?: pulumi.Input<pulumi.Input<string>[]>;
}

/**
 * An HTTP service's network: a security group that admits only the private network, a target group, a log group
 * (14 days in dev, 90 in prod) and, with `publicSubnetIds`, an internet-facing load balancer.
 * To let more traffic in, call `allowFrom`; don't add rules to `securityGroup` from outside.
 * Add an alarm on `targetGroupArnSuffix` (the definition of done for a service).
 */
export class Service extends pulumi.ComponentResource {
    public readonly securityGroup: aws.ec2.SecurityGroup;
    public readonly targetGroupArnSuffix: pulumi.Output<string>;
    public readonly url: pulumi.Output<string> | undefined;
    private readonly port: number;

    constructor(name: string, args: ServiceArgs, opts?: pulumi.ComponentResourceOptions) {
        super("acme:network:Service", name, args, opts);
        this.port = args.port;
        this.securityGroup = new aws.ec2.SecurityGroup(
            `${name}-sg`,
            {
                vpcId: args.vpcId,
                description: `${name}: internal traffic only`,
                ingress: [{ protocol: "tcp", fromPort: args.port, toPort: args.port, cidrBlocks: ["10.0.0.0/8"] }],
                tags: { team: args.team },
            },
            { parent: this },
        );
        const tg = new aws.lb.TargetGroup(
            `${name}-tg`,
            { port: args.port, protocol: "HTTP", targetType: "ip", vpcId: args.vpcId, tags: { team: args.team } },
            { parent: this },
        );
        this.targetGroupArnSuffix = tg.arnSuffix;
        new aws.cloudwatch.LogGroup(
            `${name}-logs`,
            { retentionInDays: pulumi.getStack() === "prod" ? 90 : 14, tags: { team: args.team } },
            { parent: this },
        );
        if (args.publicSubnetIds) {
            const lb = new aws.lb.LoadBalancer(
                `${name}-lb`,
                { internal: false, loadBalancerType: "application", subnets: args.publicSubnetIds, tags: { team: args.team } },
                { parent: this },
            );
            this.url = pulumi.interpolate`https://${lb.dnsName}`;
        }
        this.registerOutputs({ securityGroupId: this.securityGroup.id });
    }

    /** Admits a private CIDR to the service port; the platform reviews these rules. */
    public allowFrom(name: string, cidr: string): aws.ec2.SecurityGroupRule {
        return new aws.ec2.SecurityGroupRule(
            name,
            {
                type: "ingress",
                securityGroupId: this.securityGroup.id,
                protocol: "tcp",
                fromPort: this.port,
                toPort: this.port,
                cidrBlocks: [cidr],
            },
            { parent: this },
        );
    }
}

==> platform/identity.ts <==
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

let platformStack: pulumi.StackReference | undefined;
function platformOutputs(): pulumi.StackReference {
    platformStack = platformStack ?? new pulumi.StackReference(`acme/platform/${pulumi.getStack()}`);
    return platformStack;
}

export interface RoleArgs {
    team: string;
    /** The AWS service that assumes the role, e.g. "lambda.amazonaws.com". */
    service: string;
    /** AWS managed policies to attach; only the approved ones (see the guardrails' `iam-least-privilege`). */
    managedPolicyArns?: string[];
}

/**
 * An IAM role for a workload, with the company's permission boundary (from the platform stack) always set.
 */
export class Role extends pulumi.ComponentResource {
    public readonly arn: pulumi.Output<string>;
    public readonly name: pulumi.Output<string>;

    constructor(name: string, args: RoleArgs, opts?: pulumi.ComponentResourceOptions) {
        super("acme:iam:Role", name, args, opts);
        const role = new aws.iam.Role(
            name,
            {
                assumeRolePolicy: JSON.stringify({
                    Version: "2012-10-17",
                    Statement: [{ Effect: "Allow", Principal: { Service: args.service }, Action: "sts:AssumeRole" }],
                }),
                permissionsBoundary: platformOutputs().requireOutput("permissionsBoundaryArn"),
                tags: { team: args.team },
            },
            { parent: this },
        );
        (args.managedPolicyArns ?? []).forEach((policyArn, i) => {
            new aws.iam.RolePolicyAttachment(`${name}-managed-${i}`, { role: role.name, policyArn }, { parent: this });
        });
        this.arn = role.arn;
        this.name = role.name;
        this.registerOutputs({ arn: this.arn });
    }
}

